<div class="page-heading"><p class="eyebrow">BELAJAR. TERAPKAN. BERTUMBUH.</p><h1>Halo, <?= e($user['full_name']) ?>.</h1><p>Pantau perjalanan belajar Anda, dari pendaftaran sampai pencapaian kompetensi.</p></div>
<?php $pending=(int)one("SELECT COUNT(*) n FROM registrations WHERE user_id=? AND status IN ('pending','under_review')",[$uid])['n'];$active=0;$upcoming=0;$done=0;$total=0;foreach($enrollments as $en){if($en['start_date']>date('Y-m-d'))$upcoming++;elseif($en['end_date']>=date('Y-m-d')&&$en['status']==='active')$active++;$pr=progress($uid,(int)$en['batch_id']);$done+=$pr['done'];$total+=$pr['total'];} ?>
<div class="portal-stats"><?php foreach([['Pelatihan diikuti',count($enrollments)],['Sedang berlangsung',$active],['Akan datang',$upcoming],['Menunggu verifikasi',$pending]] as [$label,$value]): ?><div class="stat"><span><?= e($label) ?></span><strong><?= $value ?></strong></div><?php endforeach; ?></div>
<div class="portal-grid"><section class="panel"><h2>Langkah belajar berikutnya</h2><?php if($enrollments): ?><p class="muted">Kemajuan seluruh aktivitas belajar</p><div class="progress-track"><span style="width:<?= $total?(int)floor($done*100/$total):0 ?>%"></span></div><p class="muted"><?= $done ?> dari <?= $total ?> aktivitas selesai. Materi, tugas yang lulus, dan kehadiran dihitung terpisah.</p><div class="actions"><a class="btn" href="portal.php?view=learning">Lanjutkan belajar</a><a class="btn secondary" href="portal.php?view=schedule">Lihat jadwal</a></div><?php else: ?><p class="muted">Pilih program yang sesuai kebutuhan Anda. Setelah pendaftaran disetujui, materi dan jadwal pribadi akan tersedia di sini.</p><div class="actions"><a class="btn" href="programs.php">Temukan pelatihan</a></div><?php endif; ?></section><section class="panel"><h2>Kabar terbaru</h2><div class="stack"><?php foreach($notices as $notice): ?><div><h3><?= e($notice['title']) ?></h3><p class="muted"><?= e($notice['body']) ?></p></div><?php endforeach; ?><?php if(!$notices): ?><p class="muted">Belum ada kabar terbaru.</p><?php endif; ?></div></section></div>
